import React, { useEffect, useState } from 'react';
import { Container, Row, Col, Table } from 'react-bootstrap';
import { useLocation, Link } from 'react-router-dom';
import moment from 'moment';
import CompanyDetails from '../../../components/Atom/CompanyDetails';
import {
    numberToRupeesWords,
    numberWithCommas,
    formatDate,
} from '../../../utils/AllFunction';
import { usePageTitle } from '../../../hooks';

function LoanSlipReport() {

    usePageTitle({
        title: 'Loan',
        breadCrumbItems: [
            {
                path: '/loan/payment',
                label: 'Loan',
            },
            {
                path: '/loan-slip-report',
                label: 'Loan Slip Report',
                active: true,
            },
        ],
    });

    const { state } = useLocation();
    const [loanData, setLoanData] = useState({
        loanDetails: {},
        paymentHistory: [],
        staffDetails: {},
    });

    const [pdfState, setPdfState] = useState({});

    useEffect(() => {
        if (state) {
            setLoanData({
                loanDetails: state.staffDetails || {},
                repaymentSchedule: state.repaymentSchedule || [],
                paymentHistory: state.loanDetailsArray || [],
                staffDetails: state.staffDetails || {},
            });
            setPdfState(state.staffDetails || {});
        }
    }, [state]);

    const WelcomeDetails = {
        toDate: formatDate(),
        status: pdfState?.loanStatusName || '',
        loanNo: pdfState?.loanNo || '',
        interestRate: pdfState?.interestRate || '',
        loanAmount: `₹ ${numberWithCommas(pdfState?.loanAmount || 0)}.00`,
        Tenure: `${pdfState?.tenurePeriod || ''} (Months)`,
        dateofAgreement: moment(pdfState?.loanDate).format('DD-MM-YYYY'),
        disbursedMethod: pdfState?.disbursedMethodName || '',
        processFees: `₹ ${numberWithCommas(pdfState?.processFees || 0)}.00`,
    };

    const staffDetails = {
        staffCode: pdfState?.staffCode,
        staffName: pdfState?.staffName || '',
        departmentName: pdfState?.departmentName || '',
        designationName: pdfState?.designationName || '',
        address: pdfState?.address || '',
        contactNo: pdfState?.contactNo || ''
    };

    const paymentTotals = loanData.paymentHistory.reduce((acc, payment) => {
        acc.paymentAmount += parseFloat(payment.paymentAmount) || 0;
        acc.interestAmount += parseFloat(payment.interestAmount) || 0;
        acc.principalAmount += parseFloat(payment.principalAmount) || 0;
        return acc;
    }, { paymentAmount: 0, interestAmount: 0, principalAmount: 0 });

    // Split payment history into pages
    const itemsPerPage = 15;
    const paymentPages = [];
    let tempData = [...loanData.paymentHistory];

    // First page with fewer items to accommodate header
    paymentPages.push(tempData.splice(0, itemsPerPage - 5));

    // Remaining pages
    while (tempData.length > 0) {
        paymentPages.push(tempData.splice(0, itemsPerPage));
    }

    const footerFields = [
        ['Branch Manager', '', 'Managing Director']
    ];

    return (
        <Container className="letter-container my-4 p-4 bg-white" style={{ maxWidth: '800px' }}>
            {paymentPages.map((pageData, pageIndex) => (
                <div key={pageIndex} className="page-container" style={{ marginBottom: '10px' }}>
                    {pageIndex === 0 && (
                        <>
                            <Row className="mt-1 mb-1">
                                <Row className="text-center mt-2">
                                    <CompanyDetails
                                        fontSize="13px"
                                        imgSize="200px"
                                        classStyle="d-flex justify-content-center flex-column align-items-center"
                                    />
                                    <h3 style={{ color: 'black', marginTop: '10px' }}>LOAN STATEMENT</h3>
                                </Row>
                                <Row className="justify-between mt-3">
                                    <Col className="text-black" style={{ fontSize: '14px', alignSelf: 'center' }}>
                                        <Row>
                                            <Col xs={4}>
                                                <strong>Staff Name</strong>
                                            </Col>
                                            <Col xs={1}>
                                                <strong>:</strong>
                                            </Col>
                                            <Col xs={7}>{staffDetails.staffName || ''}</Col>
                                        </Row>
                                        <Row>
                                            <Col xs={4}>
                                                <strong>Staff Code</strong>
                                            </Col>
                                            <Col xs={1}>
                                                <strong>:</strong>
                                            </Col>
                                            <Col xs={7}>{staffDetails.staffCode || ''}</Col>
                                        </Row>
                                        <Row>
                                            <Col xs={4}>
                                                <strong>Address</strong>
                                            </Col>
                                            <Col xs={1}>
                                                <strong>:</strong>
                                            </Col>
                                            <Col xs={7}>{staffDetails.address || ''}</Col>
                                        </Row>
                                        <Row>
                                            <Col xs={4}>
                                                <strong>Contact</strong>
                                            </Col>
                                            <Col xs={1}>
                                                <strong>:</strong>
                                            </Col>
                                            <Col xs={7}>{staffDetails.contactNo || ''}</Col>
                                        </Row>
                                        <Row>
                                            <Col xs={4}>
                                                <strong>Department</strong>
                                            </Col>
                                            <Col xs={1}>
                                                <strong>:</strong>
                                            </Col>
                                            <Col xs={7}>{staffDetails.departmentName || ''}</Col>
                                        </Row>
                                        <Row>
                                            <Col xs={4}>
                                                <strong>Designation</strong>
                                            </Col>
                                            <Col xs={1}>
                                                <strong>:</strong>
                                            </Col>
                                            <Col xs={7}>{staffDetails.designationName || ''}</Col>
                                        </Row>
                                    </Col>
                                    <Col className="text-black" style={{ fontSize: '14px', alignSelf: 'center' }}>
                                        <Row>
                                            <Col xs={4}>
                                                <strong>Loan Number</strong>
                                            </Col>
                                            <Col xs={1}>
                                                <strong>:</strong>
                                            </Col>
                                            <Col xs={7}>{WelcomeDetails.loanNo}</Col>
                                        </Row>
                                        <Row>
                                            <Col xs={4}>
                                                <strong>Loan Amount</strong>
                                            </Col>
                                            <Col xs={1}>
                                                <strong>:</strong>
                                            </Col>
                                            <Col xs={7}>{WelcomeDetails.loanAmount}</Col>
                                        </Row>
                                        <Row>
                                            <Col xs={4}>
                                                <strong>In Words</strong>
                                            </Col>
                                            <Col xs={1}>
                                                <strong>:</strong>
                                            </Col>
                                            <Col xs={7}>{numberToRupeesWords(pdfState?.loanAmount || 0)}</Col>
                                        </Row>
                                        <Row>
                                            <Col xs={4}>
                                                <strong>Interest</strong>
                                            </Col>
                                            <Col xs={1}>
                                                <strong>:</strong>
                                            </Col>
                                            <Col xs={7}>{WelcomeDetails.interestRate} %</Col>
                                        </Row>
                                        <Row>
                                            <Col xs={4}>
                                                <strong>Process Fees</strong>
                                            </Col>
                                            <Col xs={1}>
                                                <strong>:</strong>
                                            </Col>
                                            <Col xs={7}>{WelcomeDetails.processFees} </Col>
                                        </Row>
                                        <Row>
                                            <Col xs={4}>
                                                <strong>Loan Status</strong>
                                            </Col>
                                            <Col xs={1}>
                                                <strong>:</strong>
                                            </Col>
                                            <Col xs={7}>{WelcomeDetails.status || ''}</Col>
                                        </Row>
                                        <Row>
                                            <Col xs={4}>
                                                <strong>Loan Date</strong>
                                            </Col>
                                            <Col xs={1}>
                                                <strong>:</strong>
                                            </Col>
                                            <Col xs={7}>{WelcomeDetails.dateofAgreement || ''}</Col>
                                        </Row>
                                        <Row>
                                            <Col xs={4}>
                                                <strong>Tenure Period</strong>
                                            </Col>
                                            <Col xs={1}>
                                                <strong>:</strong>
                                            </Col>
                                            <Col xs={7}>{WelcomeDetails.Tenure || ''}</Col>
                                        </Row>
                                    </Col>
                                </Row>
                            </Row>
                        </>
                    )}

                    {/* Table Data */}
                    <Table bordered hover style={{ borderColor: '#000', marginTop: pageIndex === 0 ? '50px' : '10px', tableLayout: 'fixed' }}>
                        {pageIndex === 0 && (
                            <thead>
                                <tr>
                                    <th style={{ color: 'black', textAlign: 'center', width: '16.66%' }}>Date</th>
                                    <th style={{ color: 'black', textAlign: 'center', width: '16.66%' }}>Remark</th>
                                    <th style={{ color: 'black', textAlign: 'center', width: '16.66%' }}>Payment</th>
                                    <th style={{ color: 'black', textAlign: 'center', width: '16.66%' }}>Interest</th>
                                    <th style={{ color: 'black', textAlign: 'center', width: '16.66%' }}>Principal</th>
                                    <th style={{ color: 'black', textAlign: 'center', width: '16.66%' }}>Balance</th>
                                </tr>
                            </thead>
                        )}
                        <tbody>
                            {pageData.map((row, rowIndex) => (
                                <tr key={rowIndex}>
                                    <td style={{ fontSize: '12px', color: 'black', textAlign: 'center', width: '16.66%' }}>
                                        {moment(row.paymentDate).format('DD-MM-YYYY')}
                                    </td>
                                    <td style={{ fontSize: '12px', color: 'black', textAlign: 'center', width: '16.66%' }}>
                                        {row.remark || '-'}
                                    </td>
                                    <td style={{ fontSize: '12px', color: 'black', textAlign: 'right', width: '16.66%' }}>
                                        {`₹ ${numberWithCommas(row.paymentAmount)}`}
                                    </td>
                                    <td style={{ fontSize: '12px', color: 'black', textAlign: 'right', width: '16.66%' }}>
                                        {`₹ ${numberWithCommas(row.interestAmount)}`}
                                    </td>
                                    <td style={{ fontSize: '12px', color: 'black', textAlign: 'right', width: '16.66%' }}>
                                        {`₹ ${numberWithCommas(row.principalAmount)}`}
                                    </td>
                                    <td style={{ fontSize: '12px', color: 'black', textAlign: 'right', width: '16.66%' }}>
                                        {`₹ ${numberWithCommas(row.balanceLoanAmount)}`}
                                    </td>
                                </tr>
                            ))}
                            {pageIndex === paymentPages.length - 1 && (
                                <tr>
                                    <td colSpan={2} style={{ textAlign: 'right', fontWeight: 'bold', color: 'black' }}>
                                        TOTAL:
                                    </td>
                                    <td style={{ textAlign: 'right', fontWeight: 'bold', color: 'black' }}>
                                        {`₹ ${numberWithCommas(paymentTotals.paymentAmount)}`}
                                    </td>
                                    <td style={{ textAlign: 'right', fontWeight: 'bold', color: 'black' }}>
                                        {`₹ ${numberWithCommas(paymentTotals.interestAmount)}`}
                                    </td>
                                    <td style={{ textAlign: 'right', fontWeight: 'bold', color: 'black' }}>
                                        {`₹ ${numberWithCommas(paymentTotals.principalAmount)}`}
                                    </td>
                                    <td></td>
                                </tr>
                            )}
                        </tbody>
                    </Table>

                    {/* Footer Section (only on the last page) */}
                    {pageIndex === paymentPages.length - 1 && (
                        <div style={{ marginTop: '40px', padding: '10px' }}>
                            <div style={{ fontSize: '10px', marginBottom: '20px' }}>
                                <strong>PAYMENT TERMS AND POLICIES</strong>
                                <p style={{ margin: '5px 0' }}>
                                    This receipt has been automatically generated by our software system. It serves as a digital record of your transaction.
                                </p>
                            </div>

                            {footerFields.map((row, rowIndex) => (
                                <Row key={rowIndex} className="justify-between mb-2">
                                    {row.map((col, colIndex) => (
                                        <Col
                                            key={colIndex}
                                            className="text-center"
                                            style={{
                                                fontSize: '16px',
                                                color: 'black',
                                                fontWeight: 'bold',
                                                flex: 1,
                                                marginTop: "20px"
                                            }}>
                                            {col && (
                                                <>
                                                    <div style={{ borderTop: '1px solid #000', paddingTop: '5px' }}>
                                                        <strong>{col}</strong>
                                                    </div>
                                                </>
                                            )}
                                        </Col>
                                    ))}
                                </Row>
                            ))}

                            <Row style={{ marginTop: '10px' }}>
                                <Col className="text-end" style={{ fontSize: '10px' }}>
                                    <em>Generated On: {moment().format('DD-MM-YYYY')}</em>
                                </Col>
                            </Row>
                        </div>
                    )}

                    {/* Page Break */}
                    {pageIndex < paymentPages.length - 1 && <div className="page-break"></div>}
                </div>
            ))}

            <Row className="d-print-none mt-4">
                <Col className="text-end">
                    <Link
                        to="#"
                        className="btn btn-success me-1"
                        onClick={(e) => {
                            window.print();
                        }}>
                        <i className="fa fa-print"></i> Print
                    </Link>
                </Col>
            </Row>

            <style>
                {`
                    @media print {
                        body {
                            background: white;
                            margin: 0;
                            padding: 0;
                        }
                        .page-break { 
                            page-break-before: always;
                            margin-top: 20px;
                        }
                        .letter-container {
                            max-width: 100% !important;
                            padding: 0 !important;
                            margin: 0 !important;
                        }
                        .page-container {
                            margin-bottom: 0 !important;
                        }
                        .d-print-none {
                            display: none !important;
                        }
                        table {
                            page-break-inside: auto;
                        }
                        tr {
                            page-break-inside: avoid;
                            page-break-after: auto;
                        }
                    }
                    @page {
                        size: A4;
                        margin: 10mm;
                    }
                `}
            </style>
        </Container>
    );
}

export default LoanSlipReport;